from pathlib import Path
import re, json


def sub_once(text, pattern, repl, label, flags=re.S):
    out, n = re.subn(pattern, lambda m: repl, text, count=1, flags=flags)
    if n != 1:
        raise SystemExit(f'{label}: expected 1 replacement, got {n}')
    return out

