index=index_path.read_text().replace('?v=80','?v=81').replace('</head>','<link rel="stylesheet" href="/takt-v81.css?v=81">\n</head>')
index_path.write_text(index)

pkg_path=Path('package.json')
pkg=json.loads(pkg_path.read_text());pkg['version']='8.1.0';pkg_path.write_text(json.dumps(pkg,ensure_ascii=False,separators=(',',':'))+'\n')
lock_path=Path('package-lock.json')
if lock_path.exists():
    lock=json.loads(lock_path.read_text());lock['version']='8.1.0';
    if isinstance(lock.get('packages'),dict) and '' in lock['packages']: lock['packages']['']['version']='8.1.0'
    lock_path.write_text(json.dumps(lock,ensure_ascii=False,indent=2)+'\n')

