i18n=i18n.replace('const translated=(text,lang)=>{',extra+'const translated=(text,lang)=>{')
new_translate=r'''export function translateText(text,lang){const s=String(text??''),core=s.trim();if(!core||lang==='ru')return s;let out=translated(core,lang);if(out===core){let m=core.match(/^(\d+) завершённых визитов$/);if(m)out=lang==='kk'?`${m[1]} аяқталған келу`:lang==='az'?`${m[1]} tamamlanmış görüş`:`${m[1]} yakunlangan tashrif`;m=core.match(/^Осталось (\d+) дн\.?$/);if(m)out=lang==='kk'?`${m[1]} күн қалды`:lang==='az'?`${m[1]} gün qalıb`:`${m[1]} kun qoldi`;m=core.match(/^(\d+) отзыв(ов|а)?$/);if(m)out=lang==='kk'?`${m[1]} пікір`:lang==='az'?`${m[1]} rəy`:`${m[1]} fikr`;const prefixes=['Сегодня · ','Дата: ','Клиент: ','Специалист: ','Телефон: ','Ближайший визит: '];for(const p of prefixes)if(core.startsWith(p)){const key=p.trim().replace(/:$/,'');const tr=translated(key,lang);if(tr!==key){out=tr+(p.includes(':')?': ':' · ')+core.slice(p.length);break}}}return s.replace(core,out)}'''
i18n=sub_once(i18n,r"export function translateText\(text,lang\)\{.*?\}\nexport function localizeDOM",new_translate+'\nexport function localizeDOM','translateText')

legal=r'''export function legalDoc(type,lang='ru'){const docs={
ru:{policy:['Политика конфиденциальности',['1. Takt обрабатывает только те сведения, которые необходимы для работы онлайн-записи, личного кабинета, поддержки и безопасности сервиса. К таким сведениям могут относиться Telegram ID и публичные данные профиля, выбранный язык и роль, контактные данные, сведения о специалисте, услугах, расписании, записях, отзывах, уведомлениях и технической активности.','2. Цели обработки: создание и ведение аккаунта, организация записи между клиентом и специалистом, отправка сервисных уведомлений, подтверждение и перенос визитов, поддержка пользователей, предотвращение злоупотреблений, диагностика ошибок и исполнение пользовательского соглашения.','3. Правовыми основаниями являются согласие пользователя, необходимость исполнения пользовательского соглашения и иные основания, применимые к оператору в соответствующей юрисдикции. Рекламные сообщения не включаются в обязательное согласие и требуют отдельного добровольного разрешения.','4. Данные доступны только в объёме, необходимом для работы: клиенту — его записи и публичные сведения специалиста; специалисту — сведения его клиентов и записей; уполномоченным администраторам Takt — данные, необходимые для поддержки, безопасности и эксплуатации сервиса.','5. Для технической работы Takt может использовать инфраструктурных поставщиков, включая платформу Telegram, хостинг, базу данных и сервисы доставки сообщений. Такие поставщики получают только объём данных, необходимый для выполнения соответствующей функции.','6. Данные хранятся не дольше, чем это необходимо для заявленных целей, работы аккаунта, разрешения споров и исполнения обязательных требований. После прекращения необходимости данные удаляются или обезличиваются, если закон не требует иного срока хранения.','7. Пользователь вправе запросить сведения об обработке, исправление неточных данных, удаление данных, ограничение обработки или отзыв согласия в случаях, предусмотренных применимым законодательством. Обращение направляется через раздел «Поддержка Takt».','8. Takt применяет организационные и технические меры защиты: разграничение доступа, проверку Telegram-сессии, ограничение административного доступа, защитные HTTP-заголовки, контроль ошибок и ограничение злоупотреблений. Ни одна информационная система не может гарантировать абсолютную безопасность.','9. При существенном изменении целей или условий обработки Takt может запросить повторное согласие. В интерфейсе сохраняются версия документов, дата принятия и язык согласия.','10. До коммерческого запуска оператор сервиса обязан указать свои юридические реквизиты, контакт для обращений и применимую юрисдикцию. Этот текст является продуктовой редакцией и не заменяет индивидуальную юридическую проверку.']],consent:['Согласие на обработку персональных данных',['1. Нажимая «Продолжить и согласиться», пользователь подтверждает, что ознакомился с Политикой конфиденциальности и добровольно даёт согласие на обработку данных, необходимых для использования Takt.','2. Согласие охватывает получение, запись, систематизацию, хранение, уточнение, использование, передачу техническим обработчикам в необходимом объёме, блокирование, удаление и обезличивание данных для целей работы онлайн-записи, уведомлений, поддержки и безопасности.','3. Категории данных включают данные Telegram, контактные данные, сведения об аккаунте и роли, записи, услуги, расписание, отзывы, обращения в поддержку и технические события. Специальные категории данных намеренно не запрашиваются.','4. Согласие действует до достижения целей обработки, удаления аккаунта либо отзыва согласия, если иное хранение не требуется законом или для защиты законных требований.','5. Отзыв согласия можно направить через поддержку Takt. Отзыв не влияет на законность обработки, выполненной до его получения, и может сделать невозможным дальнейшее использование функций, которым объективно требуются эти данные.','6. Согласие на рекламные и маркетинговые рассылки не входит в данный документ и при необходимости запрашивается отдельно.','7. Takt сохраняет дату принятия, язык и версии Политики, Согласия и Пользовательского соглашения для подтверждения факта принятия.']],terms:['Пользовательское соглашение',['1. Takt — программный сервис онлайн-записи. Он предоставляет специалистам инструменты расписания, услуг, клиентской базы и уведомлений, а клиентам — возможность выбрать специалиста, услугу и свободное время.','2. Специалист самостоятельно определяет содержание, стоимость, продолжительность и условия оказания своих услуг, отвечает за достоверность информации, законность деятельности и исполнение договорённостей с клиентом.','3. Takt не является стороной договора на основную услугу между клиентом и специалистом и не принимает оплату за такую услугу, если отдельная функция оплаты прямо не подключена и не описана отдельно.','4. Пользователь обязан предоставлять достоверные данные, не использовать сервис для спама, обмана, нарушения прав третьих лиц, попыток получить чужие данные или вмешательства в работу сервиса.','5. Сервис может ограничить доступ при злоупотреблении, угрозе безопасности, нарушении закона или настоящего соглашения. По возможности пользователю предоставляется понятное уведомление о причине.','6. Платный доступ специалиста предоставляется по условиям, показанным на странице подписки. При окончании оплаченного периода данные кабинета сохраняются в соответствии с политикой хранения, а доступ к части функций может быть приостановлен до продления.','7. Сервис развивается и может изменять интерфейс и функции. Существенные изменения условий публикуются в новой редакции; при необходимости запрашивается повторное принятие.','8. Takt стремится обеспечивать стабильную работу, но не гарантирует абсолютную бесперебойность внешних платформ, связи, Telegram, хостинга или сетевой инфраструктуры.','9. Вопросы, претензии и запросы по аккаунту направляются через «Поддержка Takt». Применимое право и реквизиты оператора должны быть указаны владельцем сервиса до коммерческого запуска.']]},
kk:{policy:['Құпиялылық саясаты',['1. Takt онлайн жазылу, жеке кабинет, қолдау және қауіпсіздік үшін қажет деректерді ғана өңдейді. Оларға Telegram ID, профиль деректері, тіл, рөл, байланыс деректері, маман, қызметтер, кесте, жазбалар, пікірлер және техникалық белсенділік туралы ақпарат кіруі мүмкін.','2. Өңдеу мақсаттары: аккаунт жұмысы, клиент пен маман арасындағы жазылуды ұйымдастыру, сервистік хабарламалар, қолдау, қауіпсіздік және қателерді анықтау.','3. Құқықтық негіздер — пайдаланушының келісімі, пайдаланушы келісімін орындау және тиісті юрисдикциядағы өзге заңды негіздер. Маркетингтік хабарламалар бөлек ерікті келісімді талап етеді.','4. Деректер тек қажетті көлемде қолжетімді: клиентке — өз жазбалары мен маманның ашық ақпараты; маманға — өз клиенттері мен жазбалары; Takt әкімшілеріне — қолдау және қауіпсіздікке қажет деректер.','5. Takt Telegram, хостинг, дерекқор және хабарлама жеткізу инфрақұрылымын пайдалана алады. Мұндай жеткізушілерге тек қажетті деректер беріледі.','6. Деректер мақсаттарға қажет мерзімнен ұзақ сақталмайды, егер заң басқа мерзімді талап етпесе.','7. Пайдаланушы қолдау арқылы деректерге қол жеткізу, түзету, жою, өңдеуді шектеу немесе келісімді қайтарып алу туралы өтініш бере алады.','8. Takt қолжетімділікті шектеу, Telegram-сессияны тексеру және техникалық қорғаныс шараларын қолданады, бірақ абсолют қауіпсіздікке кепілдік бермейді.','9. Маңызды өзгерістер кезінде қайта келісім сұралуы мүмкін. Құжат нұсқасы, күні және келісім тілі сақталады.','10. Коммерциялық іске қосар алдында оператордың заңды деректемелері, байланысы және қолданылатын юрисдикциясы көрсетілуі тиіс.']],consent:['Дербес деректерді өңдеуге келісім',['1. «Жалғастыру және келісу» батырмасын басу арқылы пайдаланушы саясатпен танысқанын және Takt жұмысына қажетті деректерді өңдеуге ерікті түрде келісетінін растайды.','2. Келісім деректерді алу, сақтау, нақтылау, пайдалану, қажетті техникалық өңдеушілерге беру, блоктау, жою және обезличивание әрекеттерін қамтиды.','3. Деректер санаттары: Telegram деректері, байланыс, аккаунт, рөл, жазбалар, қызметтер, кесте, пікірлер, қолдау өтініштері және техникалық оқиғалар.','4. Келісім мақсаттар орындалғанға, аккаунт жойылғанға немесе келісім қайтарылғанға дейін әрекет етеді, егер заң басқа сақтауды талап етпесе.','5. Келісімді Takt қолдауы арқылы қайтарып алуға болады. Бұл бұрын заңды орындалған өңдеуге әсер етпейді.','6. Жарнамалық және маркетингтік хабарламалар бұл келісімге кірмейді.','7. Takt келісімнің күні, тілі және құжат нұсқаларын сақтайды.']],terms:['Пайдаланушы келісімі',['1. Takt — онлайн жазылу бағдарламалық сервисі.','2. Маман өз қызметінің мазмұнына, бағасына, кестесіне, заңдылығына және орындалуына өзі жауап береді.','3. Takt негізгі қызмет бойынша клиент пен маман арасындағы шарттың тарабы болып табылмайды.','4. Спам, алдау, бөтен деректерге қол жеткізу және сервистің жұмысына кедергі жасауға тыйым салынады.','5. Қауіпсіздік немесе ережені бұзу жағдайында қолжетімділік шектелуі мүмкін.','6. Ақылы қолжетімділік жазылым бетінде көрсетілген шарттармен беріледі; мерзім аяқталғанда кейбір функциялар тоқтатылуы мүмкін.','7. Сервис дамуы мүмкін; маңызды шарттар өзгерсе, жаңа редакция жарияланады.','8. Сыртқы платформалардың абсолют үздіксіз жұмысына кепілдік берілмейді.','9. Сұрақтар мен өтініштер Takt қолдауы арқылы қабылданады.']]},
az:{policy:['Məxfilik siyasəti',['1. Takt yalnız onlayn qeyd, şəxsi kabinet, dəstək və təhlükəsizlik üçün zəruri məlumatları emal edir. Bunlara Telegram ID, profil məlumatları, dil, rol, əlaqə məlumatları, mütəxəssis, xidmətlər, cədvəl, qeydlər, rəylər və texniki fəaliyyət daxil ola bilər.','2. Emal məqsədləri: hesabın işləməsi, müştəri ilə mütəxəssis arasında qeyd, xidmət bildirişləri, dəstək, təhlükəsizlik və xətaların diaqnostikası.','3. Hüquqi əsaslar istifadəçinin razılığı, istifadəçi razılaşmasının icrası və müvafiq yurisdiksiyada tətbiq olunan digər qanuni əsaslardır. Marketinq mesajları ayrıca könüllü razılıq tələb edir.','4. Məlumatlara yalnız zəruri həcmdə çıxış verilir: müştəriyə öz qeydləri və mütəxəssisin açıq məlumatları; mütəxəssisə öz müştəriləri və qeydləri; Takt administratorlarına dəstək və təhlükəsizlik üçün lazım olan məlumatlar.','5. Takt Telegram, hostinq, verilənlər bazası və mesaj çatdırılması kimi texniki infrastrukturdan istifadə edə bilər. Bu təchizatçılara yalnız zəruri məlumat ötürülür.','6. Məlumatlar məqsədlər üçün lazım olandan artıq saxlanmır, qanun daha uzun müddət tələb etmədikdə silinir və ya anonimləşdirilir.','7. İstifadəçi Takt dəstəyi vasitəsilə məlumatlara çıxış, düzəliş, silinmə, emalın məhdudlaşdırılması və razılığın geri götürülməsi barədə müraciət edə bilər.','8. Takt girişə nəzarət, Telegram sessiyasının yoxlanması və digər texniki tədbirlər tətbiq edir, lakin heç bir sistem mütləq təhlükəsizliyə zəmanət verə bilməz.','9. Əhəmiyyətli dəyişikliklər zamanı təkrar razılıq tələb oluna bilər. Sənəd versiyası, tarix və razılıq dili saxlanılır.','10. Kommersiya istifadəsindən əvvəl operatorun hüquqi rekvizitləri, əlaqə məlumatları və tətbiq olunan yurisdiksiya göstərilməlidir.']],consent:['Şəxsi məlumatların emalına razılıq',['1. «Davam et və razılaş» düyməsini basmaqla istifadəçi siyasətlə tanış olduğunu və Takt üçün zəruri məlumatların emalına könüllü razılıq verdiyini təsdiqləyir.','2. Razılıq məlumatların alınması, qeydiyyatı, saxlanması, dəqiqləşdirilməsi, istifadəsi, zəruri texniki emalçılara ötürülməsi, bloklanması, silinməsi və anonimləşdirilməsini əhatə edir.','3. Məlumat kateqoriyaları: Telegram məlumatları, əlaqə məlumatları, hesab və rol, qeydlər, xidmətlər, cədvəl, rəylər, dəstək müraciətləri və texniki hadisələr.','4. Razılıq məqsədlər yerinə yetirilənədək, hesab silinənədək və ya razılıq geri götürülənədək qüvvədədir, qanun başqa saxlanma tələb etmədikdə.','5. Razılıq Takt dəstəyi vasitəsilə geri götürülə bilər; bu, geri götürülmədən əvvəlki qanuni emala təsir etmir.','6. Reklam və marketinq mesajları bu razılığa daxil deyil.','7. Takt razılığın tarixini, dilini və sənədlərin versiyalarını saxlayır.']],terms:['İstifadəçi razılaşması',['1. Takt onlayn qeyd üçün proqram xidmətidir.','2. Mütəxəssis xidmətlərinin məzmunu, qiyməti, cədvəli, qanuniliyi və icrasına özü cavabdehdir.','3. Takt əsas xidmət üzrə müştəri ilə mütəxəssis arasındakı müqavilənin tərəfi deyil.','4. Spam, aldatma, başqasının məlumatlarına çıxış və xidmətin işinə müdaxilə qadağandır.','5. Təhlükəsizlik və ya qayda pozuntusu zamanı giriş məhdudlaşdırıla bilər.','6. Ödənişli giriş abunə səhifəsində göstərilən şərtlərlə verilir; müddət bitdikdə bəzi funksiyalar dayandırıla bilər.','7. Xidmət inkişaf etdikcə dəyişə bilər; əhəmiyyətli şərt dəyişiklikləri yeni redaksiyada göstərilir.','8. Xarici platformaların mütləq fasiləsiz işləməsinə zəmanət verilmir.','9. Suallar və müraciətlər Takt dəstəyi vasitəsilə qəbul olunur.']]},
uz:{policy:['Maxfiylik siyosati',['1. Takt faqat onlayn yozuv, shaxsiy kabinet, yordam va xavfsizlik uchun zarur ma’lumotlarni qayta ishlaydi. Bunga Telegram ID, profil ma’lumotlari, til, rol, aloqa ma’lumotlari, mutaxassis, xizmatlar, jadval, yozuvlar, fikrlar va texnik faollik kirishi mumkin.','2. Qayta ishlash maqsadlari: akkaunt ishlashi, mijoz va mutaxassis o‘rtasida yozuvni tashkil qilish, xizmat bildirishnomalari, yordam, xavfsizlik va xatolarni aniqlash.','3. Huquqiy asoslar foydalanuvchining roziligi, foydalanuvchi kelishuvini bajarish va tegishli yurisdiksiyada qo‘llanadigan boshqa qonuniy asoslardir. Marketing xabarlari alohida ixtiyoriy rozilikni talab qiladi.','4. Ma’lumotlar faqat zarur hajmda ko‘rinadi: mijozga o‘z yozuvlari va mutaxassisning ochiq ma’lumotlari; mutaxassisga o‘z mijozlari va yozuvlari; Takt administratorlariga yordam va xavfsizlik uchun kerakli ma’lumotlar.','5. Takt Telegram, hosting, ma’lumotlar bazasi va xabar yetkazish infratuzilmasidan foydalanishi mumkin. Bunday provayderlarga faqat zarur ma’lumot beriladi.','6. Ma’lumotlar maqsadlar uchun zarur muddatdan ortiq saqlanmaydi, qonun boshqa muddatni talab qilmasa o‘chiriladi yoki anonimlashtiriladi.','7. Foydalanuvchi Takt yordami orqali ma’lumotlarga kirish, tuzatish, o‘chirish, qayta ishlashni cheklash yoki rozilikni qaytarib olishni so‘rashi mumkin.','8. Takt kirishni cheklash, Telegram sessiyasini tekshirish va boshqa texnik himoya choralarini qo‘llaydi, biroq hech bir tizim mutlaq xavfsizlikni kafolatlay olmaydi.','9. Muhim o‘zgarishlarda qayta rozilik so‘ralishi mumkin. Hujjat versiyasi, sana va rozilik tili saqlanadi.','10. Tijoriy ishga tushirishdan oldin operatorning yuridik rekvizitlari, aloqa ma’lumoti va qo‘llanadigan yurisdiksiya ko‘rsatilishi kerak.']],consent:['Shaxsiy ma’lumotlarni qayta ishlashga rozilik',['1. «Davom etish va rozilik» tugmasini bosish orqali foydalanuvchi siyosat bilan tanishganini va Takt ishlashi uchun zarur ma’lumotlarni qayta ishlashga ixtiyoriy rozilik berganini tasdiqlaydi.','2. Rozilik ma’lumotlarni olish, qayd etish, saqlash, aniqlashtirish, foydalanish, zarur texnik qayta ishlovchilarga uzatish, bloklash, o‘chirish va anonimlashtirishni qamrab oladi.','3. Ma’lumotlar toifalari: Telegram ma’lumotlari, aloqa ma’lumotlari, akkaunt va rol, yozuvlar, xizmatlar, jadval, fikrlar, yordam murojaatlari va texnik hodisalar.','4. Rozilik maqsadlar bajarilgunga, akkaunt o‘chirilgunga yoki rozilik qaytarib olingunga qadar amal qiladi, qonun boshqa saqlashni talab qilmasa.','5. Rozilik Takt yordami orqali qaytarib olinishi mumkin; bu avvalgi qonuniy qayta ishlashga ta’sir qilmaydi.','6. Reklama va marketing xabarlari bu rozilikka kirmaydi.','7. Takt rozilik sanasi, tili va hujjatlar versiyalarini saqlaydi.']],terms:['Foydalanuvchi kelishuvi',['1. Takt — onlayn yozuv dasturiy xizmati.','2. Mutaxassis o‘z xizmatining mazmuni, narxi, jadvali, qonuniyligi va bajarilishi uchun o‘zi javob beradi.','3. Takt asosiy xizmat bo‘yicha mijoz va mutaxassis o‘rtasidagi shartnomaning tomoni emas.','4. Spam, aldov, begona ma’lumotlarga kirish va xizmat ishiga aralashish taqiqlanadi.','5. Xavfsizlik yoki qoidabuzarlik holatida kirish cheklanishi mumkin.','6. Pullik kirish obuna sahifasida ko‘rsatilgan shartlarda beriladi; muddat tugaganda ayrim funksiyalar to‘xtatilishi mumkin.','7. Xizmat rivojlanishi bilan o‘zgarishi mumkin; muhim shartlar yangi tahrirda ko‘rsatiladi.','8. Tashqi platformalarning mutlaq uzluksiz ishlashi kafolatlanmaydi.','9. Savol va murojaatlar Takt yordami orqali qabul qilinadi.']]}};return (docs[lang]||docs.ru)[type]||docs.ru.policy}'''
i18n=sub_once(i18n,r"export function legalDoc\(type,lang='ru'\)\{.*?\}\nexport function faqCopy",legal+'\nexport function faqCopy','legalDoc')
# FAQ must reflect direct Telegram messaging only.
i18n=i18n.replace("Если прямой Telegram недоступен, сообщение отправит бот Takt.","Переписка идёт только в личном Telegram. Если username клиента недоступен, используйте телефон.")
i18n_path.write_text(i18n)

# Static regression checks for 8.1.
Path('test/v81.test.mjs').write_text(r'''import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const app=fs.readFileSync('public/app-v2.js','utf8'),worker=fs.readFileSync('src/worker.js','utf8'),css=fs.readFileSync('public/takt-v81.css','utf8'),landing=fs.readFileSync('public/landing.js','utf8'),pkg=JSON.parse(fs.readFileSync('package.json','utf8'));
test('8.1 version and visual patch are wired',()=>{assert.equal(pkg.version,'8.1.0');assert.match(css,/subscription-v81/);assert.match(landing,/hero-second-line/)});
test('client messaging is personal Telegram only',()=>{assert.match(app,/Переписка через Takt отключена/);assert.doesNotMatch(app,/setTimeout\(\(\)=>tg\?\.close/)});
test('month calendar supports whole-cell tap',()=>assert.match(app,/calendar-grid\.month .*calendar-day/));
test('worker is upgraded to 8.1',()=>assert.match(worker,/version:'8\.1\.0'/));
''')
print('Takt 8.1 app patch applied')
